export function lookupRealStudentName(identifier?: string | null, fallbackName?: string | null): string {
  if (!identifier && !fallbackName) return "Student";

  const candidatesToTry = [identifier, fallbackName].filter(Boolean) as string[];

  for (const raw of candidatesToTry) {
    const str = raw.trim();
    if (!str) continue;

    // 1. Direct map lookup (uppercase)
    const upper = str.toUpperCase();
    if (STUDENT_CANDIDATE_MAP[upper]?.name) {
      return STUDENT_CANDIDATE_MAP[upper].name;
    }

    // 2. Extract register number pattern (e.g. 731225AU005, 25AU005, 25IT030, etc.)
    const regMatch = str.match(/(\d{2,4}[A-Za-z]{2,4}\d{2,4}|\d{6,12})/);
    if (regMatch) {
      const regCode = regMatch[0].toUpperCase();
      const cleanReg = regCode.replace(/^7312/, "");
      if (STUDENT_CANDIDATE_MAP[cleanReg]?.name) {
        return STUDENT_CANDIDATE_MAP[cleanReg].name;
      }
      if (STUDENT_CANDIDATE_MAP[`7312${cleanReg}`]?.name) {
        return STUDENT_CANDIDATE_MAP[`7312${cleanReg}`].name;
      }
      if (STUDENT_CANDIDATE_MAP[regCode]?.name) {
        return STUDENT_CANDIDATE_MAP[regCode].name;
      }
    }

    // 3. Search by student name in map (case-insensitive substring/prefix match)
    const cleanLettersOnly = upper.replace(/[^A-Z\s]/g, "").trim();
    if (cleanLettersOnly.length >= 3 && cleanLettersOnly !== "STUDENT" && cleanLettersOnly !== "STUDENT USER") {
      const values = Object.values(STUDENT_CANDIDATE_MAP);
      const exactMatch = values.find(v => v.name.toUpperCase() === cleanLettersOnly);
      if (exactMatch) return exactMatch.name;

      const prefixMatch = values.find(v => v.name.toUpperCase().startsWith(cleanLettersOnly));
      if (prefixMatch) return prefixMatch.name;
    }
  }

  // 4. Fallback logic: if fallbackName or identifier looks like a real person's name (not "Student (...)")
  for (const candidate of candidatesToTry) {
    if (
      candidate &&
      !candidate.startsWith("Student (") &&
      candidate !== "Student User" &&
      candidate !== "Student" &&
      !candidate.includes("@") &&
      !/^\d+$/.test(candidate)
    ) {
      return candidate;
    }
  }

  // Final fallback
  const firstRaw = candidatesToTry[0] || "";
  const match = firstRaw.match(/(\d{2,4}[A-Za-z]{2,4}\d{2,4}|\d{6,12})/);
  if (match) return `Student (${match[0].toUpperCase()})`;

  return fallbackName || "Student";
}

